CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NOT NULL,first_name VARCHAR(100) NULL,last_name VARCHAR(100) NULL,role ENUM('SUPER_ADMIN','ADMIN','USER') NOT NULL DEFAULT 'USER',status ENUM('ACTIVE','DISABLED') NOT NULL DEFAULT 'ACTIVE',last_login_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uq_users_email(email),KEY idx_users_status_role(status,role));
CREATE TABLE import_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,created_by BIGINT UNSIGNED NOT NULL,file_name VARCHAR(255) NOT NULL,file_size BIGINT UNSIGNED NOT NULL,status ENUM('UPLOADED','PROCESSING','COMPLETED','FAILED','CANCELLED') NOT NULL DEFAULT 'UPLOADED',total_rows INT UNSIGNED NOT NULL DEFAULT 0,processed_rows INT UNSIGNED NOT NULL DEFAULT 0,qualified_rows INT UNSIGNED NOT NULL DEFAULT 0,rejected_rows INT UNSIGNED NOT NULL DEFAULT 0,error_message TEXT NULL,archived_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT fk_import_user FOREIGN KEY(created_by) REFERENCES users(id),KEY idx_import_status(status),KEY idx_import_created(created_at));
CREATE TABLE leads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,import_job_id BIGINT UNSIGNED NOT NULL,domain VARCHAR(253) NOT NULL,first_name VARCHAR(100) NULL,last_name VARCHAR(150) NULL,company VARCHAR(255) NULL,email VARCHAR(255) NULL,phone VARCHAR(80) NULL,country VARCHAR(100) NULL,state VARCHAR(120) NULL,city VARCHAR(120) NULL,postal_code VARCHAR(30) NULL,website_status ENUM('UNSCANNED','SCANNING','LIVE','PARKED','COMING_SOON','NO_WEBSITE','ERROR') NOT NULL DEFAULT 'UNSCANNED',business_type VARCHAR(100) NULL,lead_score TINYINT UNSIGNED NOT NULL DEFAULT 0,status ENUM('PENDING','QUALIFIED','REJECTED','MOVED_TO_PROSPECT','DELETED') NOT NULL DEFAULT 'PENDING',rejection_reason VARCHAR(255) NULL,discovery_date DATE NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT fk_lead_import FOREIGN KEY(import_job_id) REFERENCES import_jobs(id),UNIQUE KEY uq_lead_import_domain(import_job_id,domain),KEY idx_leads_domain(domain),KEY idx_leads_queue(status,website_status,country),KEY idx_leads_scan(status,website_status,import_job_id,country,id),KEY idx_leads_email(email),KEY idx_leads_score(lead_score));
CREATE TABLE prospects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_lead_id BIGINT UNSIGNED NULL,domain VARCHAR(253) NOT NULL,first_name VARCHAR(100) NULL,last_name VARCHAR(150) NULL,company VARCHAR(255) NULL,email VARCHAR(255) NULL,phone VARCHAR(80) NULL,country VARCHAR(100) NULL,state VARCHAR(120) NULL,city VARCHAR(120) NULL,postal_code VARCHAR(30) NULL,lead_score TINYINT UNSIGNED NOT NULL DEFAULT 0,status ENUM('ACTIVE','CONTACTED','WON','LOST','UNSUBSCRIBED','DELETED') NOT NULL DEFAULT 'ACTIVE',created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT fk_prospect_lead FOREIGN KEY(source_lead_id) REFERENCES leads(id),CONSTRAINT fk_prospect_user FOREIGN KEY(created_by) REFERENCES users(id),UNIQUE KEY uq_prospects_domain(domain),KEY idx_prospects_email(email),KEY idx_prospects_status(status));
CREATE TABLE campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,channel ENUM('EMAIL','WHATSAPP') NOT NULL DEFAULT 'EMAIL',provider ENUM('HOSTINGER','GMAIL','META') NOT NULL,subject VARCHAR(255) NULL,html_body MEDIUMTEXT NULL,text_body MEDIUMTEXT NULL,min_delay_seconds SMALLINT UNSIGNED NOT NULL DEFAULT 45,max_delay_seconds SMALLINT UNSIGNED NOT NULL DEFAULT 120,hourly_limit SMALLINT UNSIGNED NOT NULL DEFAULT 30,daily_limit SMALLINT UNSIGNED NOT NULL DEFAULT 200,status ENUM('DRAFT','QUEUED','RUNNING','PAUSED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'DRAFT',next_send_at DATETIME(3) NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT fk_campaign_user FOREIGN KEY(created_by) REFERENCES users(id),KEY idx_campaign_status(status),KEY idx_campaign_queue(status,next_send_at));
CREATE TABLE campaign_recipients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,prospect_id BIGINT UNSIGNED NOT NULL,status ENUM('PENDING','SENDING','SENT','FAILED','SKIPPED','BOUNCED','UNSUBSCRIBED') NOT NULL DEFAULT 'PENDING',attempt_count TINYINT UNSIGNED NOT NULL DEFAULT 0,next_attempt_at DATETIME(3) NULL,sent_at DATETIME(3) NULL,provider_message_id VARCHAR(255) NULL,last_error VARCHAR(500) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT fk_recipient_campaign FOREIGN KEY(campaign_id) REFERENCES campaigns(id),CONSTRAINT fk_recipient_prospect FOREIGN KEY(prospect_id) REFERENCES prospects(id),UNIQUE KEY uq_campaign_prospect(campaign_id,prospect_id),KEY idx_recipient_queue(status,next_attempt_at));
CREATE TABLE suppressions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) NOT NULL,reason ENUM('UNSUBSCRIBED','BOUNCE','COMPLAINT','MANUAL') NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uq_suppressions_email(email));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id VARCHAR(80) NULL,metadata JSON NULL,ip_address VARCHAR(64) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id),KEY idx_audit_created(created_at),KEY idx_audit_entity(entity_type,entity_id));
CREATE TABLE processing_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,created_by BIGINT UNSIGNED NOT NULL,countries JSON NOT NULL,status ENUM('RUNNING','COMPLETED','CANCELLED') NOT NULL DEFAULT 'RUNNING',total_rows INT UNSIGNED NOT NULL DEFAULT 0,processed_rows INT UNSIGNED NOT NULL DEFAULT 0,qualified_rows INT UNSIGNED NOT NULL DEFAULT 0,rejected_rows INT UNSIGNED NOT NULL DEFAULT 0,import_job_id BIGINT UNSIGNED NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),KEY idx_processing_status(status));
CREATE TABLE exclusion_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pattern VARCHAR(255) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uq_exclusion_pattern(pattern));
